settings.custom_css:
/* Container particelle */
#particles-background {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.particles-container {
  position: relative;
  width: 100%;
  height: 100%;
}

/* Singola particella */
.particle {
  position: absolute;
  background: #c9a96e;
  opacity: 0.1;
  border-radius: 50%;
  pointer-events: none;
  animation: float-random linear infinite;
}

/* Particelle esagonali */
.particle.hexagon {
  border-radius: 0;
  clip-path: polygon(30% 0%, 70% 0%, 100% 50%, 70% 100%, 30% 100%, 0% 50%);
  opacity: 0.08;
}

/* Animazioni casuali */
@keyframes float-random {
  0% {
    transform: translateY(100vh) rotate(0deg);
    opacity: 0;
  }
  10% {
    opacity: 0.1;
  }
  90% {
    opacity: 0.1;
  }
  100% {
    transform: translateY(-100px) rotate(360deg);
    opacity: 0;
  }
}

@keyframes float-random-2 {
  0% {
    transform: translateY(100vh) translateX(-50px) rotate(0deg);
    opacity: 0;
  }
  10% {
    opacity: 0.15;
  }
  50% {
    transform: translateY(50vh) translateX(50px) rotate(180deg);
  }
  90% {
    opacity: 0.15;
  }
  100% {
    transform: translateY(-100px) translateX(-30px) rotate(360deg);
    opacity: 0;
  }
}

@keyframes float-random-3 {
  0% {
    transform: translateY(100vh) translateX(30px) rotate(0deg) scale(0.5);
    opacity: 0;
  }
  20% {
    opacity: 0.12;
    transform: translateY(80vh) translateX(-20px) rotate(45deg) scale(0.8);
  }
  60% {
    transform: translateY(40vh) translateX(40px) rotate(180deg) scale(1.2);
  }
  90% {
    opacity: 0.12;
  }
  100% {
    transform: translateY(-100px) translateX(-40px) rotate(360deg) scale(0.3);
    opacity: 0;
  }
}

/* Responsive */
@media (max-width: 768px) {
  .particle {
    opacity: 0.06;
  }
}
